/*
 * Generates the identicon SVGs used by the fixture scenes and writes them to
 * packages/ui/scenes/demo/identicons.ts.
 *
 * Why a build step instead of a call inside the component: every identicon method in
 * @nimiq/identicons is async, and the package's `browser` entry loads an external SVG sprite
 * over the network. Neither can happen inside a pure packages/ui component (AGENTS.md "UI
 * purity" 1), so the app generates identicons in its containers and the scenes read them from
 * this generated file. Run after changing the sample addresses:
 *
 *   node scripts/build-identicons.mjs
 */
import { createRequire } from 'node:module';
import { writeFile } from 'node:fs/promises';

const require = createRequire(new URL('../apps/web/package.json', import.meta.url));
const { default: Identicons } = require('@nimiq/identicons');

/** Hand-written sample addresses: valid Nimiq addresses, no real wallet behind them. */
const SAMPLES = [
  ['ada', 'NQ47 1KS2 2TBF 0KF3 V55D 0DAH 5DXG H4VD T6A1'],
  ['bo', 'NQ25 N2DS 42KF HBX8 CTE3 SKDM 30SA MU8E 3VDK'],
  ['cem', 'NQ84 KEAH 5SKA 07VQ 2ESB Y9TK F8VS 6XQM 7J0E'],
  ['dia', 'NQ13 S39G M1HV 7TJG J8H5 HTH5 M2RC 3TGU 1NAA'],
  ['eze', 'NQ62 8JFU 1XUC 3N9Y YG1V HKQF 6JDB 7FSS P15H'],
  ['fay', 'NQ31 U0EA T0TF VBX4 1JQA FNN3 L5G6 Q4TK CY1F'],
  ['gus', 'NQ70 41YL JX2J KFSP 1V0G 1Y4T 9XFD BAR8 QDK7'],
  ['hana', 'NQ55 DJ0B RTTK 8E90 CNEQ FA4E N1L5 F5TD P1XM'],
  ['ivo', 'NQ09 TXTM 6VS9 4F5S 8CGQ 5MJA VRQN YBB1 32FL'],
  ['jo', 'NQ18 KX4C G4Y5 3JTM 0LFJ 9RB7 5Y3P 1AGB RX0C'],
  ['kai', 'NQ44 H6E4 KPYD 25AA 2XJ6 9JMU 06TH 5F2V M4EU'],
  ['lea', 'NQ27 7P2R 2NSY 3LT4 V9FC 1FHS NB1E 8JDS BB06'],
];

const entries = [];
for (const [name, address] of SAMPLES) {
  const svg = await Identicons.svg(address);
  entries.push([name, address, svg.replace(/\s+/g, ' ').trim()]);
}

const body = entries
  .map(
    ([name, address, svg]) =>
      `  ${name}: {\n    address: ${JSON.stringify(address)},\n    svg: ${JSON.stringify(svg)},\n  },`,
  )
  .join('\n');

const file = `// GENERATED by scripts/build-identicons.mjs — do not edit by hand.
//
// Nimiq identicons for the hand-written sample squads (AGENTS.md "UI purity" 5). The real app
// generates these in apps/web from each member's verified address; these are the same function
// applied to invented addresses, so the HyperFrames video and the scene gallery draw real Nimiq
// identicons with no network access and no async work inside a component.
//
// Produced with @nimiq/identicons 1.6.2.

export interface DemoIdenticon {
  readonly address: string;
  readonly svg: string;
}

export const demoIdenticons: Record<string, DemoIdenticon> = {
${body}
};

export const demoIdenticonList: readonly DemoIdenticon[] = Object.values(demoIdenticons);
`;

const out = new URL('../packages/ui/scenes/demo/identicons.ts', import.meta.url);
await writeFile(out, file);
console.log(`wrote ${entries.length} identicons to packages/ui/scenes/demo/identicons.ts`);
